const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('👥 用户管理页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('addUser', function() {\r\n    alert('➕ 添加用户功能');\r\n    console.log('添加用户');\r\n});\r\n\r\nregisterFunction('deleteUser', function() {\r\n    alert('🗑️ 删除用户功能');\r\n    console.log('删除用户');\r\n});\r\n\r\nregisterFunction('editUser', function() {\r\n    alert('✏️ 编辑用户功能');\r\n    console.log('编辑用户');\r\n});\r\n";export{n as default};
